def heap_queue_largest(numbers, n):
    import heapq

    if len(numbers) == 0:
        return []

    # Create a min-heap with all numbers and keep only the top n largest elements
    h = []
    for num in numbers:
        heapq.heappush(h, num)
        if len(h) > n:
            heapq.heapreplace(h, num)

    return sorted(h, reverse=True)

