def count_Substrings(s):
    n = len(s)
    total_count = 0

    for i in range(n):
        current_sum = int(s[i])
        if current_sum == (i + 1 - i): # Length of substring starting at i with length 1 is 1. Sum must equal length.
            total_count += 1

        for j in range(i + 1, n):
            digit_val = int(s[j])
            current_length = j - i + 1
            if (current_sum + digit_val) == current_length:
                total_count += 1

    return total_count

