def bell_number(n):
    if n == 0:
        return 1

    def binom(n, k):
        res = 1
        for i in range(k):
            res *= (n - i) // (i + 1)
        return res

    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        row_sum = sum(dp[j])
        # Bell recurrence: B(n+1) = Sum_{k=0}^{n} C(n,k)*B(k)
        # But we need to compute dp[i] using previous values.
        # Standard recurrence: B(i) = Sum_{j=0}^{i-1} binom(i-1, j) * B(j)

        val = 0
        for j in range(i):
            val += binom(i - 1, j) * dp[j]
        dp[i] = val

    return dp[n]

