def is_Monotonic(arr):
    if len(arr) <= 2:
        return True

    increasing = arr[1] >= arr[0]
    decreasing = arr[1] <= arr[0]

    for i in range(2, len(arr)):
        if not (arr[i] >= arr[i-1]) and not (arr[i] <= arr[i-1]):
            return False

    # Check consistency of direction based on first two elements
    if increasing:
        for i in range(len(arr) - 1):
            if arr[i+1] < arr[i]:
                return False
    else:
        for i in range(len(arr) - 1):
            if arr[i+1] > arr[i]:
                return False

    return True

