def sequence(n):
    if n == 1:
        return 0
    if n == 2:
        return 1

    seq = [0, 1] + [0] * (n - 2)

    for i in range(3, n + 1):
        a = seq[seq[i-2]]
        b = seq[i-1]
        seq.append(a + b) if len(seq) < n else None

    return seq[n-1]

