def next_smallest_palindrome(n):
    s = str(n)
    length = len(s)

    # Try to construct a palindrome by mirroring the left half of n
    def make_mirror(left_part, is_odd=False):
        if is_odd:
            return int(left_part + left_part[-2::-1])
        else:
            return int(left_part + left_part[::-1])

    # Case 1: Try to form a palindrome with the same length by mirroring current prefix
    half_len = (length + 1) // 2
    left_half = s[:half_len]
    candidate = make_mirror(left_half, is_odd=(length % 2 == 1))

    if int(candidate) > n:
        return candidate

    # Case 2: If the mirrored number is not greater than n (e.g., n itself is a palindrome or smaller),
    # we need to increment the left half and then mirror it.
    try:
        incremented_left = str(int(left_half) + 1)

        if len(incremented_left) > length // 2 + (length % 2):
            # Overflow occurred in the middle digit, e.g., 99 -> next is 101
            return int('1' + '0' * (length - 1))

        new_candidate = make_mirror(incremented_left, is_odd=(length % 2 == 1))

        # Check if the incremented left half caused a carry that increased length beyond original? 
        # Actually handled above. But we must ensure it's still same length unless overflow to next power of 10 pattern.
        # The logic '9' -> '10' for odd/even needs careful check against total digits.

        if len(new_candidate) == length:
            return new_candidate

    except ValueError:
        pass

    # Case 3: If we couldn't find a same-length palindrome greater than n (e.g., 9, 99), 
    # the next smallest is usually of form 10...01 with one more digit.
    if length == 2 and s[0] == '9':
        return int('1' + '0' * (length - 1))

    # General fallback for cases like 89 -> 91? No, 89 next is 91 which is not palindrome. 
    # Wait: Next smallest PALINDROME of 89 is 91? NO. Palindromes near 89 are ...77, 88, 99...
    # So for 89, next is 99. My logic above handles this via incrementing left half.

    return int('1' + '0' * (length - 1))

def eulerian_num(n, m):
    if n < 0 or m < 1:
        return 0
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            if j == 0:
                dp[i][j] = (i - 1) * dp[i-1][j]
            elif j == i:
                dp[i][j] = (i - 1) * dp[i-1][j-1]
            else:
                dp[i][j] = (i - 1) * (dp[i-1][j-1] + dp[i-1][j])
    return dp[n][m]

