                    current_max_sum = candidate
        dec[i] = current_max_sum

    # Now find max(inc[i] + dec[i]) for all i, but subtract arr[i] once because it's counted twice.
    result = 0
    for i in range(n):
        total = inc[i] + dec[i] - arr[i]
        if total > result:
            result = total

    return result

def lps(s):
    n = len(s)
    if n == 0:
        return 0

    dp = [[0] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = 2 + dp[i+1][j-1] if i < j else 0
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n - 1]

