def heap_sort(arr):
    def sift_down(heap, startpos, end):
        newitem = heap[startpos]
        # Bubble up the smaller child until hitting a leaf
        right_child = 2 * (startpos + 1) + 1
        while right_child < end:
            left_child = right_child - 1
            # If there's a larger value on the left, use it for comparison
            if newitem > heap[left_child]:
                startpos = left_child

            else:
                # Otherwise, switch to the smaller child (right)
                newitem = heap[right_child]

            right_child += 2

        end -= 1

    def sift_down_v2(heap, pos):
        """Sift down a node in a max-heap."""
        n = len(heap) - 1
        while True:
            child = 2 * pos + 1
            if child > n:
                break

            right_child = child + 1
            if right_child <= n and heap[child] < heap[right_child]:
                child += 1

            # If the parent is smaller than the largest of its children, swap them.
            if heap[pos] < heap[child]:
                heap[pos], heap[child] = heap[child], heap[pos]

                pos = child
            else:
                break

    def build_max_heap(arr):
        n = len(arr) - 1
        for i in range(n // 2, -1, -1):
            sift_down_v2(arr, i)

    # Build a max-heap from the input list
    if not arr:
        return []

    build_max_heap(arr)

    # Extract elements one by one and place them at the end of the array (sorted order)
    for i in range(len(arr), 0, -1):
        arr[0], arr[i-1] = arr[i-1], arr[0]

        sift_down_v2(arr, 0)

return arr

