def jacobsthal_num(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, (a + b) // 2 * 3 - a

    # Correction using the standard recurrence J(n) = J(n-1) + 2*J(n-2) with integer arithmetic carefully handled.
    # Standard definition: J(0)=0, J(1)=1, J(n) = J(n-1) + 2*J(n-2).

    a, b = 0, 1
    for _ in range(2, n + 1):
        c = b + 2 * a
        a, b = b, c

    return b

