def find_combinations(tuple_list):
    from itertools import combinations

    if len(tuple_list) < 2:
        return []

    result = set()
    for combo in combinations(range(len(tuple_list)), r=2):
        t1, t2 = tuple_list[combo[0]], tuple_list[combo[1]]

        # Sum first elements and second elements separately to form new tuples
        sum_first = t1[0] + t2[0]
        sum_second = t1[1] + t2[1]

        result.add((sum_first, sum_second))

    return sorted(list(result), key=lambda x: (x[0], -x[1]))

